<?php

namespace Database\Seeders;

use App\Models\User;
use Illuminate\Database\Seeder;
use Illuminate\Support\Str;
use Spatie\Permission\Models\Permission;
use Spatie\Permission\Models\Role;
use Spatie\Permission\PermissionRegistrar;

class RolesSeeder extends Seeder
{
    public const ROLES = [
        'super_admin', 'administrator', 'editor', 'writer', 'seo_manager', 'event_manager', 'media_manager',
    ];

    /** Custom (non-CRUD) permissions; per-resource CRUD permissions are generated by Filament Shield. */
    public const CUSTOM_PERMISSIONS = [
        'manage_all_articles', 'publish_article', 'approve_article', 'feature_article', 'schedule_article',
        'manage_seo', 'manage_redirects', 'manage_theme', 'manage_settings',
        'view_activity_log', 'manage_backups',
    ];

    public function run(): void
    {
        app(PermissionRegistrar::class)->forgetCachedPermissions();

        foreach (self::ROLES as $role) {
            Role::findOrCreate($role, 'web');
        }
        foreach (self::CUSTOM_PERMISSIONS as $permission) {
            Permission::findOrCreate($permission, 'web');
        }

        $this->seedSuperAdmin();
    }

    private function seedSuperAdmin(): void
    {
        $email = env('SEED_ADMIN_EMAIL');
        if (! $email) {
            $this->command?->warn('SEED_ADMIN_EMAIL not set in .env: no super admin created.');

            return;
        }

        $password = env('SEED_ADMIN_PASSWORD') ?: Str::password(20, symbols: false);
        $user = User::withTrashed()->firstOrNew(['email' => $email]);
        $isNew = ! $user->exists;
        if ($isNew) {
            $user->name = env('SEED_ADMIN_NAME', 'Site Administrator');
            $user->password = $password;
            $user->is_active = true;
            $user->email_verified_at = now();
            $user->save();
        }
        $user->assignRole('super_admin');

        if ($isNew && ! env('SEED_ADMIN_PASSWORD')) {
            $this->command?->warn("Super admin created: {$email} / {$password}  (shown once; change it after first login)");
        } else {
            $this->command?->info("Super admin ready: {$email}");
        }
    }
}
